const MODULE_ID = "mb-dice";
const TEX = `modules/${MODULE_ID}/textures`;
const range = (a, b) => Array.from({ length: b - a + 1 }, (_, i) => a + i);

// Illuminated-manuscript dice for Mythic Bastionland. Each face is a full-bleed parchment tile with a
// gilded gold-and-green foliate border and an AnglicanText blackletter numeral, baked into the texture
// (variant "full" — colour lives in the art). Generated by tools/build_mb_dice.py from the exact DSN
// face polygons; faces are warped to the UV polygon so they sit edge-to-edge on the die.
Hooks.once("diceSoNiceReady", async (dice3d) => {
  dice3d.addSystem({ id: "mb-dice", name: "MBDICE.System.Name" }, "preferred");

  // Colorset fills the bevels/edges and any face transparency so the chamfers blend with the
  // parchment. The face colour itself is baked into the images, so no body texture is needed.
  dice3d.addColorset(
    {
      name: "mb-dice",
      description: "MBDICE.Colorset.Description",
      category: "Mythic Bastionland",
      foreground: "#6b531d",   // gilt ink tint for any text labels
      background: "#e3d8bb",   // parchment cream — fills bevels/edges
      edge: "#b9a778",
      outline: "#4a3a1c",
      material: "wood",
      font: "Arial"
    },
    "preferred"
  );

  // labels[i] = face value i+1. Full-bleed parchment faces + parallel engraving heightmaps.
  const registerDie = (type, shape, names) =>
    dice3d.addDicePreset(
      {
        type,
        system: "mb-dice",
        colorset: "mb-dice",
        labels: names.map((n) => `${TEX}/${n}.webp`),
        bumpMaps: names.map((n) => `${TEX}/${n}-bump.webp`)
      },
      shape
    );

  registerDie("d6", "d6", range(1, 6).map((n) => `d6f${n}`));
  registerDie("d8", "d8", range(1, 8).map((n) => `d8f${n}`));
  // d10 atlas shows 0-9 (d10f1="0" .. d10f10="9"); order so value 1->"1" .. value 10->"0".
  registerDie("d10", "d10", [...range(2, 10), 1].map((n) => `d10f${n}`));
  registerDie("d12", "d12", range(1, 12).map((n) => `d12f${n}`));
  registerDie("d20", "d20", range(1, 20).map((n) => `d20f${n}`));

  // d4 — each physical face shows 3 numerals; the full triangular face art (d4f1..d4f4) already has
  // its triplet baked in DSN's exact layout, so we feed them as per-value `backgrounds`. `labels` must
  // be present for DSN to process backgrounds — keep them transparent so no extra numerals are drawn.
  dice3d.addDicePreset(
    {
      type: "d4",
      system: "mb-dice",
      colorset: "mb-dice",
      labels: range(1, 4).map(() => `${TEX}/d4blank.webp`),
      backgrounds: {
        labels: range(1, 4).map((n) => `${TEX}/d4f${n}.webp`),
        bumpMaps: range(1, 4).map((n) => `${TEX}/d4f${n}-bump.webp`)
      }
    },
    "d4"
  );
});
